library(here)
library(tidyverse)

OSSL reference: https://docs.soilspectroscopy.org/

src = "https://storage.googleapis.com/soilspec4gg-public/ossl_all_L0_v1.2.csv.gz"
dest = here("data", "ossl_mir_k_sample.rds")


data = read_csv(src)


# Kex Minimum Detection Level 
# Ref: https://www.sciencedirect.com/science/article/pii/S2589721722000186
kex_MDL &lt;- 0.12 # cmol(+).kg−1


set.seed(123)
data |&gt; 
    filter(!is.na(k.ext_usda.a725_cmolc.kg)) |&gt; 
    filter(if_all(starts_with("scan_mir"), ~ !is.na(.x))) |&gt; 
    filter(k.ext_usda.a725_cmolc.kg &gt;= kex_MDL) |&gt;
    slice_sample(prop=0.1) |&gt; 
    select(id.layer_uuid_txt, k.ext_usda.a725_cmolc.kg, starts_with("scan_mir")) |&gt;
    rename_with(~ str_replace(.x, "scan_mir\\.(\\d+)_abs", "wn_\\1"), .cols = starts_with("scan_mir")) |&gt; 
    rename(smp_id = id.layer_uuid_txt, kex = k.ext_usda.a725_cmolc.kg) |&gt;
    write_rds(dest, compress = "xz")
